functions.fp8:
def reference(self, layer, x, topk_weights, topk_ids_i32, buffers, top_k, output, use_batched_single_token_strict=False, use_batched_single_token_indexed=False):
    use_compact_w13 = _single_token_compact_w13_enabled()
    use_indexed_w13 = not use_compact_w13 and _single_token_indexed_w13_enabled()
    use_indexed_w2 = _single_token_indexed_w2_enabled()
    _log_runtime_route_once('SM70 FP8 MoE single-token active-expert dense path enabled (top_k=%d, experts=%d).', top_k, layer.sm70_num_experts)
    if use_indexed_w13 or use_indexed_w2:
        _log_runtime_route_once('SM70 FP8 MoE single-token indexed dense-stage path enabled (top_k=%d, w13=%s, w2=%s).', top_k, use_indexed_w13, use_indexed_w2)
    if use_compact_w13:
        _log_runtime_route_once('SM70 FP8 MoE single-token compact grouped W13 path enabled (top_k=%d).', top_k)
        sm70_ops.fp8_moe_single_token_compact_dense_w13_sm70_out(buffers['gate_up'], buffers['permuted_input'], x, topk_ids_i32, layer.w13_strided_ptrs_w, layer.w13_strided_ptrs_s, buffers['compact_w13_ptrs_w'], buffers['compact_w13_ptrs_s'], buffers['expert_offsets'], buffers['expert_offsets64'], buffers['inv_permuted_idx'], buffers['sorted_expert_ids'], layer.sm70_w13_k_dim, layer.sm70_w13_n_dim, self.group_size, layer.sm70_hidden_logical_size)
    elif use_indexed_w13:
        sm70_ops.fp8_moe_single_token_indexed_dense_w13_sm70_out(buffers['gate_up'], buffers['permuted_input'], x, topk_ids_i32, layer.w13_strided_ptrs_w, layer.w13_strided_ptrs_s, buffers['expert_offsets'], buffers['expert_offsets64'], buffers['inv_permuted_idx'], buffers['sorted_expert_ids'], layer.sm70_w13_k_dim, layer.sm70_w13_n_dim, self.group_size, layer.sm70_hidden_logical_size)
    else:
        sm70_ops.fp8_moe_single_token_dense_w13_sm70_out(buffers['gate_up'], buffers['permuted_input'], x, topk_ids_i32, layer.w13_strided_ptrs_w, layer.w13_strided_ptrs_s, buffers['expert_offsets'], buffers['expert_offsets64'], buffers['inv_permuted_idx'], buffers['sorted_expert_ids'], layer.sm70_w13_k_dim, layer.sm70_w13_n_dim, self.group_size, layer.sm70_hidden_logical_size)
    torch.ops._C.silu_and_mul(buffers['intermediate'], buffers['gate_up'])
    if use_indexed_w2:
        sm70_ops.fp8_moe_single_token_indexed_dense_stage_sm70_out(buffers['sorted_output'], buffers['intermediate'], buffers['expert_offsets'], buffers['sorted_expert_ids'], layer.w2_strided_ptrs_w, layer.w2_strided_ptrs_s, top_k, layer.sm70_w2_k_dim, layer.sm70_w2_n_dim, self.group_size)
    else:
        sm70_ops.fp8_moe_single_token_dense_stage_sm70_out(buffers['sorted_output'], buffers['intermediate'], buffers['expert_offsets'], buffers['sorted_expert_ids'], layer.w2_strided_ptrs_w, layer.w2_strided_ptrs_s, top_k, layer.sm70_w2_k_dim, layer.sm70_w2_n_dim, self.group_size)
    if _single_token_weighted_reduce_enabled():
        _log_runtime_route_once('SM70 FP8 MoE single-token weighted-reduce path enabled (top_k=%d).', top_k)
        sm70_ops.awq_moe_single_token_weighted_reduce_out(buffers['sorted_output'], topk_weights, buffers['inv_permuted_idx'], output, top_k, layer.sm70_hidden_logical_size)
    else:
        torch.ops._moe_C.moe_unpermute(buffers['sorted_output'], topk_weights, buffers['inv_permuted_idx'], buffers['expert_offsets64'][:top_k + 1], top_k, output)
    return output
